∀ {P A D : Type} (policy : DefiKernel.Atomic.Policy P A D) (owed : DefiKernel.Atomic.Outstanding P A D),
  @List.Nodup.{0} (DefiKernel.Atomic.Lane P A D) (@DefiKernel.Atomic.Policy.lanes P A D policy) →
    @List.Nodup.{0} P (@DefiKernel.Atomic.Policy.participants P A D policy) →
      @List.Nodup.{0} (Prod.{0, 0} (DefiKernel.Atomic.Lane P A D) P)
        (@List.map.{0, 0} (DefiKernel.Atomic.Residual P A D) (Prod.{0, 0} (DefiKernel.Atomic.Lane P A D) P)
          (fun r =>
            @Prod.mk.{0, 0} (DefiKernel.Atomic.Lane P A D) P (@DefiKernel.Atomic.Residual.lane P A D r)
              (@DefiKernel.Atomic.Residual.principal P A D r))
          (@DefiKernel.Atomic.residuals P A D policy owed))

∀ {P A D : Type} (policy : DefiKernel.Atomic.Policy P A D) (owed : DefiKernel.Atomic.Outstanding P A D),
  @List.Nodup.{0} (DefiKernel.Atomic.Lane P A D) (@DefiKernel.Atomic.Policy.lanes P A D policy) →
    @List.Nodup.{0} P (@DefiKernel.Atomic.Policy.participants P A D policy) →
      @List.Nodup.{0} (DefiKernel.Atomic.Residual P A D) (@DefiKernel.Atomic.residuals P A D policy owed)

∀ {P A D : Type} [inst : DecidableEq.{1} P] [inst_1 : DecidableEq.{1} A] [inst_2 : DecidableEq.{1} D]
  [inst_3 : Fintype.{0} P] [inst_4 : Fintype.{0} A] [inst_5 : Fintype.{0} D] {cfg : DefiKernel.Composition.Config P A D}
  {boundary : DefiKernel.Composition.Boundary P A D} {index : Nat}
  {history : List.{0} (DefiKernel.Composition.OutputObservation A)} {step : DefiKernel.Composition.Step P A D}
  {pre : DefiKernel.Composition.World P A D} {result : DefiKernel.Composition.StepResult P A D},
  @DefiKernel.Composition.StepSound P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 cfg boundary index history step pre
      result →
    ∀ (cell : DefiKernel.Typed.Cell P A D),
      @Eq.{1} Rat
        (@DefiKernel.Typed.State.balance P A D
          (@DefiKernel.Typed.ExecutionResult.state P A D (@DefiKernel.Composition.StepResult.world P A D result)) cell)
        (@HAdd.hAdd.{0, 0, 0} Rat Rat Rat (@instHAdd.{0} Rat Rat.instAdd)
          (@DefiKernel.Typed.State.balance P A D (@DefiKernel.Typed.ExecutionResult.state P A D pre) cell)
          (@DefiKernel.Atomic.receiptEffect P A D inst inst_1 inst_2
            (@DefiKernel.Composition.StepResult.receipt P A D result) cell))

∀ {P A D : Type} [inst : DecidableEq.{1} P] [inst_1 : DecidableEq.{1} A] [inst_2 : DecidableEq.{1} D]
  (policy : DefiKernel.Atomic.Policy P A D) (owed : DefiKernel.Atomic.Outstanding P A D) (principal p : P)
  (receipt : DefiKernel.Composition.Receipt P A D) (lane : DefiKernel.Atomic.Lane P A D),
  @Ne.{1} P p principal →
    @Eq.{1} Rat (@DefiKernel.Atomic.updateOutstanding P A D inst inst_1 inst_2 policy owed principal receipt lane p)
      (owed lane p)

