      m →
    @Eq.{1} (DefiKernel.Atomic.Outstanding P A D) (@DefiKernel.Atomic.Machine.outstanding P A D m)
      (@DefiKernel.Atomic.outstandingFromAttempts P A D inst inst_1 inst_2 policy boundaries
        (@DefiKernel.Interleaving.Machine.attempts P A D (@DefiKernel.Atomic.Machine.speculative P A D m)))
